{
  "requirements": [
    {
      "required_fact": "遥测代理默认的数据采集间隔是多少？",
      "source_ids": ["E1S1"],
      "evidence_finding": "原文 E1S1 明确说明遥测代理默认每 45 秒采集一次主机指标。","supported": true,
      "answer": "默认每 45 秒采集一次数据。"
    },
    {
      "required_fact": "一次最多上传多少条记录？",
      "source_ids": ["E1S1"],
      "evidence_finding": "原文 E1S1 明确说明每批最多上传 800 条记录，并澄清该数值指记录数量而非字节数。","supported": true,
      "answer": "一次最多上传 800 条记录。"
    },
    {
      "required_fact": "本地保留期限是否改变采样间隔？",
      "source_ids": ["E2S1"],
      "evidence_finding": "原文 E2S1 明确指出保留期限只描述已上传数据在磁盘上的存续时间，不改变指标采样频率。","supported": true,
      "answer": "不会改变采样间隔。"
    }
  ]
}

{
  "requirements": [
    {
      "required_fact": "边缘节点执行增量同步的条件",
      "source_ids": ["E1S1"],
      "evidence_finding": "原文明确指出两个必要条件：远端清单版本必须高于本地版本，且本地基线文件的摘要校验必须通过。若远端版本相同或更低则结束检查；若摘要不一致则转入完整同步准备状态。",
      "supported": true,
      "answer": "只有当远端清单版本高于本地版本，并且本地基线文件的摘要校验通过时，节点才执行增量同步。"
    },
    {
      "required_fact": "摘要校验失败时的处理方式",
      "source_ids": ["E2S1"],
      "evidence_finding": "原文规定不得自动删除本地副本，也不得用空文件覆盖。处理措施包括保存诊断快照、标记同步为 blocked，并等待维护人员确认完整同步窗口。在此期间现有副本以只读方式提供服务。",
      "supported": true,
      "answer": "摘要校验失败时不得自动删除本地副本或覆盖为空文件；节点应保存诊断快照、标记同步为 blocked，并等待维护人员确认完整同步窗口（确认前现有副本继续以只读方式提供服务）。"
    },
    {
      "required_fact": "是否允许删除本地副本来强制重新拉取",
      "source_ids": ["E2S1"],
      "evidence_finding": "原文明确禁止在摘要校验失败时自动删除本地副本，也未提及允许用空文件覆盖或手动删除以强制重拉的机制。",
      "supported": false,
      "answer": ""
    }
  ]
}

{
  "requirements": [
    {
      "required_fact": "证书进入常规轮换的剩余有效期阈值",
      "source_ids": ["E1S1"],
      "evidence_finding": "原文明确说明'证书剩余有效期少于 21 天时进入常规轮换队列'。",
      "supported": true,
      "answer": "证书距离到期少于 21 天时进入常规轮换。"
    },
    {
      "required_fact": "当剩余有效期少于 72 小时且新证书域名校验失败时，系统应采取的动作",
      "source_ids": ["E2S1"],
      "evidence_finding": "原文规定'控制器必须保留当前证书，暂停自动切换，并发出 severity=critical 告警'，同时'不得绕过域名检查，也不得把校验失败记录成轮换成功'。",
      "supported": true,
      "answer": "系统必须保留当前证书、暂停自动切换并发出 severity=critical 告警；可以准备候选证书，但不得绕过域名检查，也不得将此次操作记录为轮换成功。"
    }
  ]
}

{
  "requirements": [
    {
      "required_fact": "归档任务按什么对象计算压缩上限",
